syntax:
extern "C" {
    #include <stdio.h>  // Or use C++ equivalents like <cstdio>
    // Implementation note: This prevents name mangling for functions inside this block.
}

code_example:
#include <cstdio>
#include <iostream>

int main() {
    // Using C function with extern "C" linkage implicitly
    std::printf("Hello, C++ world!\n");  // Calls the unmangled C function
    return 0;
}
